function assertPolicyAnswer(output, context) {
  const parsed = typeof output === 'string' ? JSON.parse(output) : output;
  const errors = [];

  if (!['approve', 'deny', 'escalate'].includes(parsed.decision)) {
    errors.push('decision must be approve, deny, or escalate');
  }
  if (context.vars.citation_required && (!parsed.citations || parsed.citations.length === 0)) {
    errors.push('missing required citation');
  }
  if (context.vars.slice === 'outside_refund_window' && parsed.decision === 'approve') {
    errors.push('outside-window case cannot approve automatic refund');
  }

  return errors.length === 0
    ? { pass: true, score: 1 }
    : { pass: false, score: 0, reason: errors.join('; ') };
}

module.exports = assertPolicyAnswer;
